<?php
$q = mysqli_query($koneksi, "SELECT p.*, pm.namapeminjam, pm.kelas, COUNT(d.iddetilpeminjaman) AS jumlahitem, COALESCE(SUM(d.jumlahpinjam),0) AS totalunit FROM peminjaman p LEFT JOIN peminjam pm ON pm.idpeminjam=p.idpeminjam LEFT JOIN detilpeminjaman d ON d.idpeminjaman=p.idpeminjaman WHERE p.status IN ('Menunggu','Dipinjam') GROUP BY p.idpeminjaman ORDER BY p.idpeminjaman DESC");
?>
<div class="page-heading"><div><span class="eyebrow">TRANSAKSI</span><h1>Data Peminjaman</h1><p>Menampilkan pengajuan dan peminjaman yang belum dikembalikan. Barang yang sudah kembali ada di menu Pengembalian.</p></div><a class="btn btn-primary" href="index.php?halaman=createpeminjaman"><i class="fas fa-plus mr-1"></i> Tambah Peminjaman</a></div>
<div class="card modern-card"><div class="card-body p-0"><div class="table-responsive"><table class="table modern-table mb-0"><thead><tr><th>ID</th><th>Peminjam</th><th>Kelas</th><th>Tanggal Pinjam</th><th>Jenis Alat</th><th>Total Unit</th><th>Status</th><th>Aksi</th></tr></thead><tbody>
<?php if (!$q || mysqli_num_rows($q)===0): ?><tr><td colspan="8" class="text-center text-muted p-4">Belum ada data peminjaman yang aktif.</td></tr><?php else: while($r=mysqli_fetch_assoc($q)): ?><tr><td>#<?= (int)$r['idpeminjaman'] ?></td><td><?=htmlspecialchars($r['namapeminjam']??'-')?></td><td><?=htmlspecialchars($r['kelas']??'-')?></td><td><?=function_exists('tanggalIndonesia')?tanggalIndonesia($r['tanggalpinjam']):htmlspecialchars($r['tanggalpinjam'])?></td><td><?= (int)$r['jumlahitem'] ?> jenis</td><td><?= (int)$r['totalunit'] ?> unit</td><td><span class="status-badge <?= $r['status']==='Menunggu'?'status-pending':($r['status']==='Ditolak'?'status-rejected':'status-borrowed') ?>"><?=htmlspecialchars($r['status'])?></span></td><td><a class="btn btn-sm btn-outline-primary" href="index.php?halaman=showpeminjaman&id=<?=(int)$r['idpeminjaman']?>">Detail</a><?php if($r['status']==='Menunggu'): ?><form action="proses/prosespeminjaman.php?aksi=status" method="post" class="d-inline"><input type="hidden" name="idpeminjaman" value="<?=(int)$r['idpeminjaman']?>"><input type="hidden" name="status" value="Dipinjam"><button class="btn btn-sm btn-success" title="Setujui" onclick="return confirm('Setujui peminjaman ini? Stok setiap alat akan dikurangi.')"><i class="fas fa-check"></i></button></form><form action="proses/prosespeminjaman.php?aksi=status" method="post" class="d-inline"><input type="hidden" name="idpeminjaman" value="<?=(int)$r['idpeminjaman']?>"><input type="hidden" name="status" value="Ditolak"><button class="btn btn-sm btn-danger" title="Tolak" onclick="return confirm('Tolak pengajuan ini?')"><i class="fas fa-times"></i></button></form><?php endif; ?></td></tr><?php endwhile; endif; ?>
</tbody></table></div></div></div>
